import pandas as pd
import gurobipy as gp
from gurobipy import GRB

# Path to the prepared inputs JSON
DATA_PATH = "work/Variant29/prepared_inputs.json"

# Load the data
CSVQA_DATA = pd.read_json(DATA_PATH, typ='series').to_dict()

# Containers for tables
items = {}
categories = {}
usage = {}
capacity = {}
bundles = {}
incompat_pairs = []
prerequisites = {}

# Parse logical records
for family, records in CSVQA_DATA['logical_records'].items():
    for record in records:
        values = record['values']
        if family == 'item':
            ref = values['item_ref']
            items[ref] = {
                'category': values['category'],
                'unit_benefit_cents': int(values['unit_benefit_cents']),
                'item_fee_cents': int(values['item_fee_cents']),
                'min_lot': int(values['minimum_lot']),
                'max_order': int(values['maximum_order']),
                'authorized': int(values['authorized'])
            }
        elif family == 'category':
            cat = values['category']
            categories[cat] = {
                'activation_fee_cents': int(values['activation_fee_cents']),
                'min_quantity': int(values['minimum_quantity']),
                'max_quantity': int(values['maximum_quantity'])
            }
        elif family == 'usage':
            item_ref = values['item_ref']
            resource = values['resource']
            amount = int(values['amount'])
            usage[(item_ref, resource)] = amount
        elif family == 'capacity_ledger':
            resource = values['resource']
            amount = int(values['amount'])
            capacity[resource] = capacity.get(resource, 0) + amount
        elif family == 'bundle':
            a = values['item_a']
            b_item = values['item_b']
            bundles[(a, b_item)] = int(values['bonus_cents'])
        elif family == 'incompatible':
            incompat_pairs.append((values['item_a'], values['item_b']))
        elif family == 'requires':
            prerequisites[values['item_ref']] = values['prerequisite_ref']

# Keep only authorized items
authorized_items = {i: p for i, p in items.items() if p['authorized'] == 1}
items = authorized_items

# Filter prerequisites: keep only those where the item is authorized
prerequisites = {i: prereq for i, prereq in prerequisites.items() if i in items}

# Filter bundles: both items must be authorized
bundles = {pair: bonus for pair, bonus in bundles.items() if pair[0] in items and pair[1] in items}

# Filter incompatibilities: both items must be authorized
incompat_pairs = [(a, b) for a, b in incompat_pairs if a in items and b in items]

# Create the model
m = gp.Model()
m.setParam('MIPGap', 1e-06)

# Decision variables
q = {i: m.addVar(vtype=GRB.INTEGER, name=f'q_{i}') for i in items}
y = {i: m.addVar(vtype=GRB.BINARY, name=f'y_{i}') for i in items}
z = {c: m.addVar(vtype=GRB.BINARY, name=f'z_{c}') for c in categories}
b = {pair: m.addVar(vtype=GRB.BINARY, name=f'b_{pair[0]}_{pair[1]}') for pair in bundles}

# Quantity bounds (lot size)
for i, params in items.items():
    min_lot = params['min_lot']
    max_order = params['max_order']
    m.addConstr(q[i] >= min_lot * y[i])
    m.addConstr(q[i] <= max_order * y[i])

# Category activation constraints
for i, params in items.items():
    c = params['category']
    m.addConstr(z[c] >= y[i])
for c in categories:
    sum_y = gp.quicksum(y[i] for i, p in items.items() if p['category'] == c)
    m.addConstr(z[c] <= sum_y)

# Category quantity limits
for c, cat_params in categories.items():
    sum_q = gp.quicksum(q[i] for i, p in items.items() if p['category'] == c)
    m.addConstr(sum_q >= cat_params['min_quantity'] * z[c])
    m.addConstr(sum_q <= cat_params['max_quantity'] * z[c])

# Incompatibility constraints
for a, b_item in incompat_pairs:
    m.addConstr(y[a] + y[b_item] <= 1)

# Prerequisite constraints
for i, prereq in prerequisites.items():
    if prereq in y:
        m.addConstr(y[i] <= y[prereq])
    else:
        # Prerequisite is unauthorized; item cannot be ordered
        m.addConstr(y[i] == 0)

# Bundle bonus constraints
for (a, b_item), bonus in bundles.items():
    m.addConstr(b[(a, b_item)] <= y[a])
    m.addConstr(b[(a, b_item)] <= y[b_item])
    m.addConstr(b[(a, b_item)] >= y[a] + y[b_item] - 1)

# Resource capacity constraints
for r, cap in capacity.items():
    expr = gp.quicksum(usage.get((i, r), 0) * q[i] for i in items)
    m.addConstr(expr <= cap)

# Objective: maximize net benefit
obj = gp.quicksum(
    items[i]['unit_benefit_cents'] * q[i] - items[i]['item_fee_cents'] * y[i]
    for i in items
) - gp.quicksum(
    categories[c]['activation_fee_cents'] * z[c] for c in categories
) + gp.quicksum(
    bundles[pair] * b[pair] for pair in bundles
)
m.setObjective(obj, GRB.MAXIMIZE)

# Optimize
m.optimize()

