y = {i: m.addVar(vtype=GRB.BINARY, name=f"y_{i}") for i in items}
z = {c: m.addVar(vtype=GRB.BINARY, name=f"z_{c}") for c in categories}
b = {pair: m.addVar(vtype=GRB.BINARY, name=f"b_{pair[0]}_{pair[1]}") for pair in bundles}

