for i, prereq in prerequisites.items():
    m.addConstr(y[i] <= y[prereq])
# Items with an unauthorized prerequisite cannot be ordered
unauth_prereq_items = set(items) - set(prerequisites.keys())
for i in unauth_prereq_items:
