import json
import pandas as pd
import pulp

# Path to the prepared inputs JSON
DATA_PATH = "work/Variant29/prepared_inputs.json"

# Load the JSON data as a dictionary of tables
data = pd.read_json(DATA_PATH, typ='series')
tables = {t['name']: t['rows'] for t in data['tables']}

# Helper: convert amounts to base units
UNIT_FACTORS = {
    "kwh": 1000,   # to wh
    "liter": 1000, # to ml
    "hour": 60,    # to minute
}
def to_base(amount, unit):
    return int(amount * UNIT_FACTORS.get(unit, 1))

# Parse tables into DataFrames
items_df      = pd.DataFrame(tables.get("item", []))
usage_df      = pd.DataFrame(tables.get("usage", []))
capacity_df   = pd.DataFrame(tables.get("capacity_ledger", []))
category_df   = pd.DataFrame(tables.get("category", []))
incompat_df   = pd.DataFrame(tables.get("incompatible", []))
requires_df   = pd.DataFrame(tables.get("requires", []))
bundle_df     = pd.DataFrame(tables.get("bundle", []))

# Keep only authorized items
items_df = items_df[items_df["authorized"] == 1].copy()

# Build dictionaries for quick lookup
items = {}
for _, row in items_df.iterrows():
    items[row["item_ref"]] = {
        "category": row["category"],
        "unit_benefit_cents": int(row["unit_benefit_cents"]),
        "item_fee_cents": int(row["item_fee_cents"]),
        "min_lot": int(row["minimum_lot"]),
        "max_order": int(row["maximum_order"]),
    }

# Usage: (item_ref, resource) -> amount per unit in base units
usage = {}
for _, row in usage_df.iterrows():
    key = (row["item_ref"], row["resource"])
    usage[key] = to_base(row["amount"], row["unit"])

# Capacity ledger: resource -> total capacity in base units
capacity = {}
for _, row in capacity_df.iterrows():
    res = row["resource"]
    capacity[res] = capacity.get(res, 0) + to_base(row["amount"], row["unit"])

# Category parameters
categories = {}
for _, row in category_df.iterrows():
    categories[row["category"]] = {
        "activation_fee_cents": int(row["activation_fee_cents"]),
        "min_quantity": int(row["minimum_quantity"]),
        "max_quantity": int(row["maximum_quantity"]),
    }

# Incompatibilities: only keep pairs where both items are authorized
incompat_pairs = [
    (row["item_a"], row["item_b"])
    for _, row in incompat_df.iterrows()
    if row["item_a"] in items and row["item_b"] in items
]

# Prerequisites: keep only those where both items are authorized
prerequisites = {}
for _, row in requires_df.iterrows():
    item = row["item_ref"]
    prereq = row["prerequisite_ref"]
    if item in items and prereq in items:
        prerequisites[item] = prereq

# Bundles: only keep pairs where both items are authorized
bundles = {}
for _, row in bundle_df.iterrows():
    a = row["item_a"]
    b = row["item_b"]
    if a in items and b in items:
        bundles[(a, b)] = int(row["bonus_cents"])

# Identify items that have a prerequisite that is not authorized
unauthorized_prereq_items = {
    item for item, prereq in prerequisites.items() if prereq not in items
}

# Create the PuLP model
prob = pulp.LpProblem("Bakery_Order_Optimization", pulp.LpMaximize)

# Decision variables
q = {i: pulp.LpVariable(f"q_{i}", lowBound=0, cat=pulp.LpInteger) for i in items}
y = {i: pulp.LpVariable(f"y_{i}", cat=pulp.LpBinary) for i in items}
z = {c: pulp.LpVariable(f"z_{c}", cat=pulp.LpBinary) for c in categories}
b = {pair: pulp.LpVariable(f"b_{pair[0]}_{pair[1]}", cat=pulp.LpBinary) for pair in bundles}

# Quantity bounds (lot size)
for i, params in items.items():
    min_lot = params["min_lot"]
    max_order = params["max_order"]
    prob += q[i] >= min_lot * y[i]
    prob += q[i] <= max_order * y[i]

# Category activation constraints
for i, params in items.items():
    c = params["category"]
    prob += z[c] >= y[i]
for c in categories:
    prob += z[c] <= pulp.lpSum(y[i] for i, p in items.items() if p["category"] == c)

# Category quantity limits
for c, cat_params in categories.items():
    sum_q = pulp.lpSum(q[i] for i, p in items.items() if p["category"] == c)
    prob += sum_q >= cat_params["min_quantity"] * z[c]
    prob += sum_q <= cat_params["max_quantity"] * z[c]

# Incompatibility constraints
for a, b_item in incompat_pairs:
    prob += y[a] + y[b_item] <= 1

# Prerequisite constraints
for i, prereq in prerequisites.items():
    prob += y[i] <= y[prereq]

# Forbid items whose prerequisite is unauthorized
for i in unauthorized_prereq_items:
    prob += y[i] == 0

# Bundle bonus constraints
for (a, b_item), bonus in bundles.items():
    prob += b[(a, b_item)] <= y[a]
    prob += b[(a, b_item)] <= y[b_item]
    prob += b[(a, b_item)] >= y[a] + y[b_item] - 1

# Resource capacity constraints
for r, cap in capacity.items():
    expr = pulp.lpSum(usage.get((i, r), 0) * q[i] for i in items)
    prob += expr <= cap

# Objective: maximize net benefit
obj = (
    pulp.lpSum(
        items[i]["unit_benefit_cents"] * q[i] - items[i]["item_fee_cents"] * y[i]
        for i in items
    )
    - pulp.lpSum(
        categories[c]["activation_fee_cents"] * z[c] for c in categories
    )
    + pulp.lpSum(
        bundles[pair] * b[pair] for pair in bundles
    )
)
prob += obj

# Solve the problem
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Report the maximum net benefit in USD cents
if pulp.LpStatus[prob.status] == "Optimal":
    print(f"Maximum net benefit: {int(pulp.value(prob.objective))} cents")
else:
    print(f"Optimization ended with status {pulp.LpStatus[prob.status]}")
